    data = json.load(f)

result = json.loads(data['result'])
exps = result['data']['experiments']

def extract_crm_checkpoint(exp):
    paths = []
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    match = re.findall(r'--crm_checkpoint\s+(\S+)', cmd)
    if match:
        paths.extend(match)
    match = re.findall(r'--crm_ckpt\s+(\S+)', cmd)
    if match:
        paths.extend(match)
    for key in ['crm_checkpoint', 'crm_ckpt', 'checkpoint_source']:
        if key in spec:
            paths.append(spec[key])
    return list(set(paths)) if paths else ['NOT FOUND IN COMMAND']

def extract_K(exp):
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    match = re.findall(r'--K\s+(\d+)', cmd)
    if match:
        return match[0]
    hyp = exp.get('hypothesis', '')
    match = re.findall(r'K\s*=\s*(\d+)', hyp)
    if match:
        return match[0]
    return 'NOT FOUND'

def extract_tau(exp):
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    match = re.findall(r'--conformal_threshold\s+([\d.]+)', cmd)
    return match[0] if match else 'NOT FOUND'

def extract_norm(exp):
    spec = exp.get('spec', {})
    cmd = spec.get('command', '')
    match = re.findall(r'--max_correction_norm\s+([\d.]+)', cmd)
    return match[0] if match else 'NOT FOUND'

